-- helpers ----------------------------------------------------------------------------------
function PTCT_Today() return floor(SystemTime() / 86400) end
function PTCT_Owns()
	if GetTask(PTCT_T_OWN) == 1 then return 1 end
	return nil
end
function PTCT_Level()
	local l = GetTask(PTCT_T_LEVEL)
	if l < 1 then l = 1 end
	if l > 4 then l = 4 end
	return l
end
-- building level 0..5 (0 = not built)
function PTCT_BLevel(id)
	if not id or not PTCT_B[id] then return 0 end
	local v = GetTask(PTCT_T_BLD0 + id)
	if v < 0 then v = 0 end
	if v > PTCT_BMAX then v = PTCT_BMAX end
	return v
end
function PTCT_Built(id)
	if PTCT_BLevel(id) > 0 then return 1 end
	return nil
end
-- level - 1 (0..4): extra rounds / stamina / picks of the building
function PTCT_BBonus(id)
	local l = PTCT_BLevel(id)
	if l < 1 then return 0 end
	return l - 1
end
-- resource / hung thinh multiplier of the VNG buildings: level 1-2 x1, 3-4 x2, 5 x3
function PTCT_BMult(id)
	local l = PTCT_BLevel(id)
	if l >= 5 then return 3 end
	if l >= 3 then return 2 end
	return 1
end
function PTCT_BMaxLv()
	local m = PTCT_Level() + 1
	if m > PTCT_BMAX then m = PTCT_BMAX end
	return m
end
-- upgrade level l -> l + 1: money, Xich dong (resource 3), Luong thao (resource 4), contribution needed (kept)
function PTCT_UpCost(id, l)
	local b = PTCT_B[id]
	return b.cost * l, 2 * l, 2 * l, 30 * l
end
-- daily counters packed as day * 100 + n
function PTCT_DayN(t)
	local v = GetTask(t)
	if floor(v / 100) ~= PTCT_Today() then return 0 end
	return mod(v, 100)
end
function PTCT_DaySet(t, n) SetTask(t, PTCT_Today() * 100 + n) end
-- Xich Dong Thao picks per round (Phong chien xa level 3 and 5: one less)
function PTCT_78_Need() return PTCT_78_PICK - floor(PTCT_BBonus(4) / 2) end
function PTCT_Res(k) return GetTask(PTCT_T_RES0 + k) end
function PTCT_AddRes(k, n)
	if k < 1 or k > 4 then return 0 end
	local v = GetTask(PTCT_T_RES0 + k) + n
	if v < 0 then v = 0 end
	SetTask(PTCT_T_RES0 + k, v)
	return v
end
function PTCT_Contri() return GetTask(PTCT_T_CONTRI) end
function PTCT_AddContri(n)
	local v = GetTask(PTCT_T_CONTRI) + (n or 0)
	if v < 0 then v = 0 end
	SetTask(PTCT_T_CONTRI, v)
	return v
end
-- VNG city var id -> task value (nil when not mapped)
function PTCT_CityVar(id)
	if id and id >= 21 and id <= 38 then return PTCT_T_CV21 + id - 21 end
	return nil
end
function PTCT_MercTotal()
	local s = 0
	local i = 0
	while i < 16 do
		s = s + GetTask(PTCT_T_CV21 + i)
		i = i + 1
	end
	return s
end
function PTCT_CityName() return PTCT_TXT.city .. GetName() end
function PTCT_No() CloseDialog() end
function PTCT_Say1(text) Talk(1, "PTCT_No", text) end

